package com.innovatus.studentrecords.view; import com.innovatus.studentrecords.controller.OTPController; import com.innovatus.studentrecords.utils.DialogUtil; import javax.swing.*; import java.awt.*; public class ForgotPasswordFrame extends BaseFrame {public ForgotPasswordFrame(){super("Forgot Password");JTextField e=new JTextField();JButton b=button("Send OTP");setLayout(new GridLayout(3,1,10,10));add(new JLabel("Registered email:"));add(e);add(b);b.addActionListener(x->{try{OTPFrame.setEmail(e.getText());OTPFrame.setController(new OTPController());OTPFrame.controller().request(e.getText());dispose();new OTPFrame().setVisible(true);}catch(Exception z){DialogUtil.error(this,z.getMessage());}});}}
